import { getTripActivationStatus, hasAnyActivatedTrip } from './metadata';
import { OfflineError } from './errors';
import { networkStore } from '@/shared/store/network';

interface RouteOperations<T> {
  local: () => Promise<T>;
  remote: () => Promise<T>;
}

function assertRemoteAvailable(offlineMessage: string, tripId?: string) {
  const status = networkStore.realStatus;

  if (status === 'online') {
    return;
  }

  throw new OfflineError(
    status === 'unknown' ? '인터넷 연결을 아직 확인하지 못했어요. 잠시 후 다시 시도해주세요.' : offlineMessage,
    { action: status === 'unknown' ? 'ONLINE_REQUIRED' : 'ACTIVATE_PROMPT', tripId },
  );
}

function assertWritesAllowed() {
  if (networkStore.override !== null) {
    throw new OfflineError('네트워크 화면 테스트 중에는 저장·삭제할 수 없어요. 강제 설정을 해제해주세요.', {
      action: 'ONLINE_REQUIRED',
    });
  }
}

/** Trip 조회의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripQuery<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 조회는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildQuery<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요', tripId);
  return await operations.remote();
}

/** Trip 쓰기의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripMutation<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  assertWritesAllowed();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 수정할 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 쓰기는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildMutation<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  assertWritesAllowed();

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 수정할 수 있어요', tripId);
  return await operations.remote();
}
// ========================================
// Trip Repository - 활성화 상태에 따른 Local/Remote 분기
// ========================================

import { routeTripQuery, routeTripMutation } from '@/shared/services/offline-prep/router';
import * as TripLocal from '../lib/trip-local';
import * as TripApi from '../api/trips';
import type { Trip, CreateTripRequest, UpdateTripRequest, DeleteTripResponse } from '../model';

/**
 * Trip Repository
 *
 * - 활성화된 Trip 있음: Local DB 사용
 * - 비활성 상태: Server API 사용
 * - Router가 활성화 상태에 따라 자동 분기
 */
export const TripRepository = {
  /**
   * 모든 여행 조회
   */
  getAll: async (): Promise<Trip[]> => {
    return await routeTripQuery({
      local: () => TripLocal.getTripsLocal(),
      remote: async () => {
        const response = await TripApi.fetchAllTrips();
        return response.data;
      },
    });
  },

  /**
   * 특정 여행 조회
   */
  getById: async (id: string): Promise<Trip | undefined> => {
    return await routeTripQuery({
      local: () => TripLocal.getTripByIdLocal(id),
      remote: async () => {
        // TODO: fetchTripById API 필요시 추가
        const response = await TripApi.fetchAllTrips();
        return response.data.find((trip) => trip.id === id);
      },
    });
  },

  /**
   * 여행 생성
   */
  create: async (data: CreateTripRequest): Promise<Trip> => {
    return await routeTripMutation({
      local: () => TripLocal.createTripLocal(data),
      remote: () => TripApi.fetchCreateTrip(data),
    });
  },

  /**
   * 여행 수정
   */
  update: async (id: string, data: UpdateTripRequest): Promise<Trip> => {
    return await routeTripMutation({
      local: () => TripLocal.updateTripLocal(id, data),
      remote: () => TripApi.fetchUpdateTrip(id, data),
    });
  },

  /**
   * 여행 삭제 (Soft Delete)
   */
  delete: async (id: string): Promise<DeleteTripResponse> => {
    return await routeTripMutation({
      local: () => TripLocal.deleteTripLocal(id),
      remote: () => TripApi.fetchDeleteTrip(id),
    });
  },
};
// ========================================
// Schedule Repository - 활성화 상태에 따른 Local/Remote 분기
// ========================================

import { routeChildQuery, routeChildMutation } from '@/shared/services/offline-prep/router';
import * as ScheduleLocal from '../lib/schedule-local';
import * as ScheduleApi from '../api/schedules';
import type { Schedule, CreateScheduleRequest, UpdateScheduleRequest } from '../model';

/**
 * Schedule Repository
 *
 * - 활성화된 Trip: Local DB 사용
 * - 비활성 Trip: Server API 사용
 * - routeChildQuery/Mutation이 tripId 기반으로 자동 분기
 */
export const ScheduleRepository = {
  /**
   * 여행의 일정 목록 조회
   */
  getByTripId: async (tripId: string): Promise<Schedule[]> => {
    return await routeChildQuery(tripId, {
      local: () => ScheduleLocal.getSchedulesLocal(tripId),
      remote: () => ScheduleApi.fetchSchedules(tripId),
    });
  },

  /**
   * 특정 일정 조회
   * @param id - 일정 ID
   * @param tripId - 여행 ID (라우팅 판단용)
   */
  getById: async (id: string, tripId: string): Promise<Schedule | undefined> => {
    return await routeChildQuery(tripId, {
      local: () => ScheduleLocal.getScheduleByIdLocal(id),
      remote: () => ScheduleApi.fetchScheduleById(id),
    });
  },

  /**
   * 여행의 일정 개수 조회
   * - 로컬 전용 (오프라인 지도 다운로드 트리거용)
   */
  getCount: async (tripId: string): Promise<number> => {
    return await ScheduleLocal.getScheduleCountLocal(tripId);
  },

  /**
   * 일정 생성
   */
  create: async (data: CreateScheduleRequest): Promise<Schedule> => {
    return await routeChildMutation(data.tripId, {
      local: () => ScheduleLocal.createScheduleLocal(data),
      remote: () => ScheduleApi.fetchCreateSchedule(data),
    });
  },

  /**
   * 일정 수정
   * - tripId를 먼저 조회하여 라우팅 결정
   */
  update: async (id: string, data: UpdateScheduleRequest): Promise<Schedule> => {
    // 1. 일정의 tripId 조회 (라우팅을 위해 필요)
    const tripId = await ScheduleLocal.getScheduleTripIdLocal(id);

    if (!tripId) {
      throw new Error(`Schedule not found: ${id}`);
    }

    return await routeChildMutation(tripId, {
      local: () => ScheduleLocal.updateScheduleLocal(id, data),
      remote: () => ScheduleApi.fetchUpdateSchedule(id, data),
    });
  },

  /**
   * 일정 삭제 (Soft Delete)
   * - tripId를 먼저 조회하여 라우팅 결정
   */
  delete: async (id: string): Promise<{ id: string; deletedAt: string }> => {
    // 1. 일정의 tripId 조회 (라우팅을 위해 필요)
    const tripId = await ScheduleLocal.getScheduleTripIdLocal(id);

    if (!tripId) {
      throw new Error(`Schedule not found: ${id}`);
    }

    return await routeChildMutation(tripId, {
      local: () => ScheduleLocal.deleteScheduleLocal(id),
      remote: () => ScheduleApi.fetchDeleteSchedule(id),
    });
  },
};
// ========================================
// Expense Repository - 활성화 상태에 따른 Local/Remote 분기
// ========================================

import { routeChildQuery, routeChildMutation } from '@/shared/services/offline-prep/router';
import * as ExpenseLocal from '../lib/expense-local';
import * as ExpenseApi from '../api/expenses';
import type { Expense, CreateExpenseRequest, UpdateExpenseRequest } from '../model';

/**
 * Expense Repository
 *
 * - 활성화된 Trip: Local DB 사용
 * - 비활성 Trip: Server API 사용
 * - routeChildQuery/Mutation이 tripId 기반으로 자동 분기
 */
export const ExpenseRepository = {
  /**
   * 전체 경비 조회 (로컬 전용)
   * - 활성화된 여행의 경비만 포함
   */
  getAll: async (): Promise<Expense[]> => {
    return await ExpenseLocal.getAllExpensesLocal();
  },

  /**
   * 여행별 경비 조회
   */
  getByTripId: async (tripId: string): Promise<Expense[]> => {
    return await routeChildQuery(tripId, {
      local: () => ExpenseLocal.getExpensesByTripIdLocal(tripId),
      remote: () => ExpenseApi.fetchExpensesByTripId(tripId),
    });
  },

  /**
   * 일정별 경비 조회
   * - scheduleId로 tripId를 먼저 조회하여 라우팅 결정
   */
  getByScheduleId: async (scheduleId: string): Promise<Expense[]> => {
    // 1. scheduleId로 tripId 조회
    const tripId = await ExpenseLocal.getTripIdByScheduleIdLocal(scheduleId);

    if (!tripId) {
      throw new Error(`Schedule not found: ${scheduleId}`);
    }

    // 2. tripId로 라우팅 적용
    return await routeChildQuery(tripId, {
      local: () => ExpenseLocal.getExpensesByScheduleIdLocal(scheduleId),
      remote: () => ExpenseApi.fetchExpensesByScheduleId(scheduleId),
    });
  },

  /**
   * 경비 생성
   */
  create: async (data: CreateExpenseRequest): Promise<Expense> => {
    return await routeChildMutation(data.tripId, {
      local: () => ExpenseLocal.createExpenseLocal(data),
      remote: () => ExpenseApi.fetchCreateExpense(data),
    });
  },

  /**
   * 경비 수정
   * - tripId를 먼저 조회하여 라우팅 결정
   */
  update: async (id: string, data: UpdateExpenseRequest): Promise<Expense> => {
    // 1. 경비의 tripId 조회 (라우팅을 위해 필요)
    const tripId = await ExpenseLocal.getExpenseTripIdLocal(id);

    if (!tripId) {
      throw new Error(`Expense not found: ${id}`);
    }

    return await routeChildMutation(tripId, {
      local: () => ExpenseLocal.updateExpenseLocal(id, data),
      remote: () => ExpenseApi.fetchUpdateExpense(id, data),
    });
  },

  /**
   * 경비 삭제 (Soft Delete)
   * - tripId를 먼저 조회하여 라우팅 결정
   */
  delete: async (id: string): Promise<{ id: string; deletedAt: string }> => {
    // 1. 경비의 tripId 조회 (라우팅을 위해 필요)
    const tripId = await ExpenseLocal.getExpenseTripIdLocal(id);

    if (!tripId) {
      throw new Error(`Expense not found: ${id}`);
    }

    return await routeChildMutation(tripId, {
      local: () => ExpenseLocal.deleteExpenseLocal(id),
      remote: () => ExpenseApi.fetchDeleteExpense(id),
    });
  },
};

