 * - 비활성+오프라인 시 OfflineError 발생 → UI에서 "활성화하기" 안내
 *
 * @param tripId - 여행 ID (필수)
 *
 * @example
 * ```tsx
 * const { data: expenses, isLoading } = useGetTripExpenses('trip-id-123');
 * ```
 */
export const useGetTripExpenses = (tripId: string) => {
  return useQuery({
    queryKey: expenseQueryKeys.byTrip(tripId),
    queryFn: () => ExpenseRepository.getByTripId(tripId),
    staleTime: 5 * 60 * 1000, // 5분
    gcTime: 10 * 60 * 1000, // 10분
  });
};
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { TripRepository } from '../repository/trip-repository';
import type { CreateTripRequest } from '../model';
import { tripQueryKeys } from './keys';

/**
 * 여행 생성 Mutation Hook
 *
 * - Repository를 통해 활성화 상태에 따라 Local/Remote 자동 분기
 * - Client-Side ID: 외부에서 ID 생성하여 전달
 *
 * @example
 * ```tsx
 * const { mutate, isPending } = useCreateTrip();
 * mutate({
 *   id: generateId(), // Client-Side ID: 외부에서 ID 생성
 *   name: 'Tokyo Trip',
 *   destination: 'Tokyo',
 *   country: 'Japan',
 *   // ...
 * });
 * ```
 */
export const useCreateTrip = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: CreateTripRequest) => TripRepository.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: tripQueryKeys.all(),
      });
    },
    onError: (error) => {
      console.error('❌ Failed to create trip:', error);
    },
  });
};
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { ScheduleRepository } from '../repository/schedule-repository';
import type { CreateScheduleRequest } from '../model';
import { scheduleQueryKeys } from './keys';
import { routeQueryKeys } from '@/entities/route/data/keys';

/**
 * 일정 생성 Mutation Hook
 *
 * - Repository를 통해 활성화 상태에 따라 Local/Remote 자동 분기
 * - Client-Side ID: 외부에서 ID 생성하여 전달
 *
 * ⚠️ 주의: Policy 체크는 컴포넌트에서 useAppPolicy()로 수행
 *
 * @example
 * ```tsx
 * const policy = useAppPolicy(tripId);
 * const { mutate, isPending } = useCreateSchedule();
 *
 * if (!policy.createSchedule.allowed) {
 *   return <DisabledMessage reason={policy.createSchedule.reason} />;
 * }
 *
 * mutate({
 *   id: generateId(),
 *   tripId: 'trip-id',
 *   title: 'Eiffel Tower Visit',
 *   location: 'Eiffel Tower',
 *   scheduledAt: '2024-03-15T09:00:00+09:00',
 * });
 * ```
 */
export const useCreateSchedule = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: CreateScheduleRequest) => ScheduleRepository.create(data),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: scheduleQueryKeys.list(variables.tripId),
      });
      queryClient.invalidateQueries({
        queryKey: scheduleQueryKeys.count(variables.tripId),
      });
      // Route 캐시 무효화 (경로 재계산 필요)
      queryClient.invalidateQueries({
        queryKey: routeQueryKeys.byTrip(variables.tripId),
      });
    },
    onError: (error) => {
      console.error('❌ Failed to create schedule:', error);
    },
  });
};
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { ExpenseRepository } from '../repository/expense-repository';
import type { CreateExpenseRequest } from '../model';
import { expenseQueryKeys } from './keys';

/**
