 *
 * - Repository를 통해 활성화 상태에 따라 Local/Remote 자동 분기
 * - Client-Side ID: 외부에서 ID 생성하여 전달
 *
 * @example
 * ```tsx
 * const { mutate, isPending } = useCreateExpense();
 * mutate({
 *   id: generateId(),
 *   tripId: 'trip-id',
 *   title: 'Eiffel Tower Ticket',
 *   amount: '25.50',
 *   currency: 'EUR',
 *   category: '관광',
 *   date: '2024-03-15',
 * });
 * ```
 */
