import { expenseEntity } from '../entities/expense';
import { okResponse, okListResponse, deleteResponse } from './_envelope';

// ========================================
// Trip Response Schemas (API 응답)
// ========================================

/**
 * 단일 여행 응답
 * POST /api/trips, PATCH /api/trips/:id
 */
export const tripResponse = okResponse(tripEntity);

/**
 * 여행 목록 응답
 * GET /api/trips
 */
export const tripListResponse = okListResponse(tripEntity);

/**
 * 여행 삭제 응답
 * DELETE /api/trips/:id
 */
export const deleteTripResponse = deleteResponse;

/**
 * 여행 활성화 응답
 * POST /api/trips/:id/activate
 *
 * 활성화 시 모든 Trip 메타데이터 + 해당 Trip의 Schedule/Expense 반환
 */
export const activateTripResponse = z.object({
  success: z.literal(true),
  data: z.object({
    trips: z.array(tripEntity),
    schedules: z.array(scheduleEntity),
    expenses: z.array(expenseEntity),
  }),
  message: z.string().optional(),
});
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { ScheduleRepository } from '../repository/schedule-repository';
import type { UpdateScheduleRequest } from '../model';
import { scheduleQueryKeys } from './keys';
import { routeQueryKeys } from '@/entities/route/data/keys';

/**
 * 일정 수정 Mutation Hook
 *
 * - Repository를 통해 활성화 상태에 따라 Local/Remote 자동 분기
 *
 * @example
 * ```tsx
 * const { mutate, isPending } = useUpdateSchedule();
 * mutate({
 *   id: 'schedule-id',
 *   data: {
 *     title: 'Updated Schedule',
 *     scheduledAt: '2024-03-15T14:30:00.000Z',
 *   },
 * });
 * ```
 */
export const useUpdateSchedule = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: UpdateScheduleRequest }) => ScheduleRepository.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: scheduleQueryKeys.base,
      });
      // Route 캐시 무효화 (경로 재계산 필요)
      queryClient.invalidateQueries({
        queryKey: routeQueryKeys.base,
      });
    },
    onError: (error) => {
      console.error('❌ Failed to update schedule:', error);
    },
  });
};
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { ExpenseRepository } from '../repository/expense-repository';
import type { UpdateExpenseRequest } from '../model';
import { expenseQueryKeys } from './keys';

/**
 * 경비 수정 Mutation Hook
 *
 * - Repository를 통해 활성화 상태에 따라 Local/Remote 자동 분기
 *
 * @example
 * ```tsx
 * const { mutate, isPending } = useUpdateExpense();
 * mutate({
 *   id: 'expense-id',
 *   data: {
 *     title: 'Updated Expense',
 *     amount: '50.00',
 *     category: '식사',
 *   },
 * });
 * ```
 */
export const useUpdateExpense = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: UpdateExpenseRequest }) => ExpenseRepository.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: expenseQueryKeys.base,
      });
    },
    onError: (error) => {
      console.error('❌ Failed to update expense:', error);
    },
  });
};
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { TripRepository } from '../repository/trip-repository';
import type { UpdateTripRequest } from '../model';
import { tripQueryKeys } from './keys';

/**
 * 여행 수정 Mutation Hook
 *
 * - Repository를 통해 활성화 상태에 따라 Local/Remote 자동 분기
 *
 * @example
 * ```tsx
 * const { mutate, isPending } = useUpdateTrip();
 * mutate({
 *   id: 'trip-id',
 *   data: {
 *     name: 'Updated Trip Name',
 *     destination: 'New Destination',
 *   },
 * });
 * ```
 */
export const useUpdateTrip = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: UpdateTripRequest }) => TripRepository.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: tripQueryKeys.all(),
      });
    },
    onError: (error) => {
      console.error('❌ Failed to update trip:', error);
    },
  });
};
