  { name: '일정 삭제', run: () => ScheduleRepository.delete('schedule-b', 'trip-b'), result: deleted,
    remote: ScheduleApi.fetchDeleteSchedule, local: ScheduleLocal.deleteScheduleLocal },
  { name: '경비 수정', run: () => ExpenseRepository.update('expense-b', 'trip-b', { title: '수정' }), result: expense,
    remote: ExpenseApi.fetchUpdateExpense, local: ExpenseLocal.updateExpenseLocal },
  { name: '경비 삭제', run: () => ExpenseRepository.delete('expense-b', 'trip-b'), result: deleted,
    remote: ExpenseApi.fetchDeleteExpense, local: ExpenseLocal.deleteExpenseLocal },
  { name: '일정별 경비 조회', run: () => ExpenseRepository.getByScheduleId('schedule-b', 'trip-b'), result: [expense],
    remote: ExpenseApi.fetchExpensesByScheduleId, local: ExpenseLocal.getExpensesByScheduleIdLocal },
