import { z } from 'zod';

// ========================================
// Trip Entity Schema (DB와 1:1 매핑)
// ========================================

/**
 * Trip Entity Schema (강제 계약)
 * - 모든 앱이 준수해야 하는 도메인 모델
 * - DB와 1:1 매핑
 * - 날짜: ISO 8601 datetime string
 */
export const tripEntity = z.object({
  // Client-Side ID 필드
  id: z.string().ulid(),
  createdAt: z.string().datetime({ offset: true }),
  updatedAt: z.string().datetime({ offset: true }),
  deletedAt: z.string().datetime({ offset: true }).nullable().optional(),
  version: z.number().default(1).optional(),

  // 비즈니스 필드
  userId: z.string().ulid().nullable(), // 인증 추가 전까지 nullable
  name: z.string(),
  destination: z.string(),
  country: z.string().nullable(),
  baseCurrency: z.string(), // 여행 기본 통화
  latitude: z.string().nullable(), // DB decimal → string
  longitude: z.string().nullable(),
  cityId: z.number().nullable(),
  startDate: z.string().datetime({ offset: true }),
  endDate: z.string().datetime({ offset: true }),
});
import { z } from 'zod';

// ========================================
// Response Envelope Factories
// ========================================
//
// 정책: 모든 API 응답은 { success: true, data: ... } 구조를 따른다.
// 각 entity response 파일은 이 factory를 통해 동일한 envelope를 만든다.

export const okResponse = <T extends z.ZodTypeAny>(dataSchema: T) =>
  z.object({
    success: z.literal(true),
    data: dataSchema,
  });

export const okListResponse = <T extends z.ZodTypeAny>(itemSchema: T) =>
  z.object({
    success: z.literal(true),
    data: z.array(itemSchema),
  });

/**
 * Soft delete 응답
 * DELETE /api/{entity}/:id
 *
 * trip/schedule/expense 모두 동일 shape.
 */
export const deleteResponse = z.object({
  success: z.literal(true),
  data: z.object({
    id: z.string().ulid(),
    deletedAt: z.string().datetime({ offset: true }),
  }),
});
import apiClient from '@/shared/api/fetcher';
import { createTripRequest, updateTripRequest } from '@repo/schema/requests/trip';
import { tripResponse, tripListResponse, deleteTripResponse } from '@repo/schema/responses/trip';
import type {
  GetAllTripsResponse,
  CreateTripRequest,
  CreateTripResponse,
  UpdateTripRequest,
  UpdateTripResponse,
  DeleteTripResponse,
} from '../model';

// ========================================
// Trip API Functions
// ========================================

/**
 * 전체 여행을 조회합니다.
 * @returns 모든 여행 정보
 */
export const fetchAllTrips = async (): Promise<GetAllTripsResponse> => {
  const data = await apiClient.get('/api/trips');

  const validated = tripListResponse.parse(data);
  return validated;
};

/**
 * 새로운 여행을 생성합니다.
 * @param data - 여행 생성 요청 데이터
 * @returns 생성된 여행 정보
 */
export const fetchCreateTrip = async (data: CreateTripRequest): Promise<CreateTripResponse> => {
  const validatedInput = createTripRequest.parse(data);
  const responseData = await apiClient.post('/api/trips', validatedInput);

  const validated = tripResponse.parse(responseData);
  return validated.data;
};

/**
 * 여행 정보를 수정합니다.
 * @param id - 여행 ID (ULID)
 * @param data - 수정할 여행 데이터
 * @returns 수정된 여행 정보
 */
export const fetchUpdateTrip = async (id: string, data: UpdateTripRequest): Promise<UpdateTripResponse> => {
  const validatedInput = updateTripRequest.parse(data);
  const responseData = await apiClient.put(`/api/trips/${id}`, validatedInput);

  const validated = tripResponse.parse(responseData);
  return validated.data;
};

/**
 * 여행을 삭제합니다.
 * @param id - 여행 ID (ULID)
 * @returns 삭제된 여행 정보 (id, deletedAt)
 */
export const fetchDeleteTrip = async (id: string): Promise<DeleteTripResponse> => {
  const responseData = await apiClient.delete(`/api/trips/${id}`);

  const validated = deleteTripResponse.parse(responseData);
  return validated.data;
};
import { getTripActivationStatus, hasAnyActivatedTrip } from './metadata';
import { OfflineError } from './errors';
import { networkStore } from '@/shared/store/network';

interface RouteOperations<T> {
  local: () => Promise<T>;
  remote: () => Promise<T>;
}

function assertRemoteAvailable(offlineMessage: string, tripId?: string) {
  const status = networkStore.realStatus;

  if (status === 'online') {
    return;
  }

  throw new OfflineError(
    status === 'unknown' ? '인터넷 연결을 아직 확인하지 못했어요. 잠시 후 다시 시도해주세요.' : offlineMessage,
    { action: status === 'unknown' ? 'ONLINE_REQUIRED' : 'ACTIVATE_PROMPT', tripId },
  );
}

function assertWritesAllowed() {
  if (networkStore.override !== null) {
    throw new OfflineError('네트워크 화면 테스트 중에는 저장·삭제할 수 없어요. 강제 설정을 해제해주세요.', {
      action: 'ONLINE_REQUIRED',
    });
  }
}

/** 여행 목록은 활성 여행이 있으면 기존 Local 목록을 사용한다. */
export async function routeTripListQuery<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요');
  return await operations.remote();
}

/** Trip 단건 조회는 대상 여행의 활성 여부로 분기한다. */
export async function routeTripQuery<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  return routeChildQuery(tripId, operations);
